<?php namespace App\Policies; use App\Models\Order; use App\Models\User; class OrderPolicy { public function viewAny(User $user): bool { return in_array($user->role, ['student', 'vendor', 'admin']); } public function view(User $user, Order $order): bool { return $user->role === 'admin' || $user->id === $order->user_id || ($order->stall && $user->id === $order->stall->user_id); } public function create(User $user): bool { return $user->role === 'student'; } public function cancel(User $user, Order $order): bool { return $user->role === 'student' && $user->id === $order->user_id && $order->status === 'Pending'; } public function updateStatus(User $user, Order $order): bool { return $user->role === 'vendor' && $order->stall && $user->id === $order->stall->user_id; } }